      player.z = clamp(player.z, town.bounds.minZ, town.bounds.maxZ);
    }
  }

  function punch() {
    const player = state.player;
    if (!player.onFoot) return 0;
    const fx = Math.sin(player.heading);
    const fz = Math.cos(player.heading);
