    for (const car of state.cars) {
      if (car.driver !== 'police') continue;
      const dx = car.x - player.x;
      const dz = car.z - player.z;
      if (Math.hypot(dx, dz) > PUNCH_DIST + 1) continue;
      car.x += fx * 1.5;
      car.z += fz * 1.5;
      car.speed = 0;
      hit = true;
    }
    if (hit) {
