    head.position.y = 1.75;
    group.add(head);
    group.userData = { body, head };
    group.visible = false;
    scene.add(group);
    return group;
  }

  const pedPool = [];
  for (let i = 0; i < MAX_PEDS; i += 1) pedPool.push(makePedMesh());

  // Mara Quinn, on foot: teal jacket, dark jeans, unmistakable.
  const playerMesh = new THREE.Group();
